   185|export function classifyIssue(signal: IssueSignal): IssueClassification {
   186|  const desc = signal.description.trim();
   187|  const lower = desc.toLowerCase();
   188|
   189|  let matched = signal.hintKind
   190|    ? ISSUE_PATTERNS.find((p) => p.kind === signal.hintKind)
   191|    : ISSUE_PATTERNS.find((p) => p.tokens.test(lower));
   192|
   193|  if (!matched) {
   194|    matched = ISSUE_PATTERNS.find((p) => p.kind === 'lint_type_issue')!;
   195|  }
   196|
   197|  // Confidence band: high if multiple distinct tokens match, medium if only
   198|  // one pattern matches, low if we fell back to default lint bucket.
   199|  const matchCount = ISSUE_PATTERNS.filter((p) => p.tokens.test(lower)).length;
   200|  let confidence: ConfidenceBand;
   201|  if (signal.hintKind && matchCount >= 1) confidence = 'high';
   202|  else if (matchCount >= 2) confidence = 'high';
   203|  else if (matchCount === 1) confidence = 'medium';
   204|  else confidence = 'low';
   205|
   206|  const reasoning = `pattern=${matched.kind} matches=${matchCount} hint=${signal.hintKind ?? 'none'}`;
   207|
   208|  return {
   209|    kind: matched.kind,
   210|    area: matched.area,
   211|    preferredAgent: matched.agent,
   212|    confidence,
   213|    reasoning,
   214|  };
